const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
    let cmb = countries.filter(ee.Filter.eq('country_na', 'Cambodia'));
    let cmbCount = await cmb.size().getInfo();
    if (cmbCount === 0) {
      cmb = countries.filter(ee.Filter.eq('name', 'Cambodia'));
      cmbCount = await cmb.size().getInfo();
    }
    if (cmbCount === 0) {
      console.log('C1');
      return;
    }
    const cambodia = ee.Feature(cmb.first()).geometry();

    const years = [2014, 2015, 2016, 2017];
    const targetMonths = [2, 10]; // February, October

    async function monthlyStats(year, month) {
      const start = ee.Date.fromYMD(year, month, 1);
      const end = start.advance(1, 'month');

      function getCol(version) {
        const t = ee.ImageCollection(`MODIS/${version}/MOD14A1`).filterDate(start, end).select('MaxFRP');
        const a = ee.ImageCollection(`MODIS/${version}/MYD14A1`).filterDate(start, end).select('MaxFRP');
        return t.merge(a).filterBounds(cambodia);
      }
      let col = getCol('006');
      let size = await col.size().getInfo();
      if (size === 0) {
        col = getCol('061');
        size = await col.size().getInfo();
      }
      if (size === 0) {
        return { year, month, imgs: 0, usedPix: 0, fireSum: null, empty: true };
      }

      const binCol = col.map(function(img) {
        const bin = img.select('MaxFRP').gt(0).rename('fire').toUint8();
        return bin.copyProperties(img, ['system:time_start']);
      });
      const monthly = binCol.sum().rename('fire'); // count of detections per pixel in month
      const dictSum = await monthly.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: cambodia,
        scale: 1000,
        maxPixels: 1e9
      }).get('fire').getInfo();
      const dictCount = await monthly.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: cambodia,
        scale: 1000,
        maxPixels: 1e9
      }).get('fire').getInfo();

      return { year, month, imgs: size || 0, usedPix: dictCount || 0, fireSum: dictSum, empty: false };
    }

    let febTotal = 0, octTotal = 0;
    let febImgs = 0, octImgs = 0;
    let febUsedPixTotal = 0, octUsedPixTotal = 0;
    let anyEmpty = false, anyNull = false;

    for (const y of years) {
      // February
      const f = await monthlyStats(y, 2);
      if (f.empty) anyEmpty = true;
      if (f.fireSum === null || Number.isNaN(f.fireSum)) anyNull = true;
      console.log(`${y}-02 imgs:${f.imgs} usedPix:${f.usedPix} fireSum:${f.fireSum === null ? 'null' : f.fireSum}`);
      febTotal += (f.fireSum || 0);
      febImgs += f.imgs;
      febUsedPixTotal += f.usedPix;

      // October
      const o = await monthlyStats(y, 10);
      if (o.empty) anyEmpty = true;
      if (o.fireSum === null || Number.isNaN(o.fireSum)) anyNull = true;
      console.log(`${y}-10 imgs:${o.imgs} usedPix:${o.usedPix} fireSum:${o.fireSum === null ? 'null' : o.fireSum}`);
      octTotal += (o.fireSum || 0);
      octImgs += o.imgs;
      octUsedPixTotal += o.usedPix;
    }

    // Core checks
    if (anyEmpty || febImgs === 0 || octImgs === 0) {
      console.log('C1');
      return;
    }
    if (febUsedPixTotal === 0 || octUsedPixTotal === 0) {
      console.log('C2');
      return;
    }
    if (anyNull || febTotal === null || octTotal === null || !isFinite(febTotal) || !isFinite(octTotal)) {
      console.log('C3');
      return;
    }

    console.log(`Total Feb FireSum: ${febTotal}, Images: ${febImgs}`);
    console.log(`Total Oct FireSum: ${octTotal}, Images: ${octImgs}`);

    // Final Answer
    if (febTotal > octTotal) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
